import subprocess, re, os, json

D = "/Users/kristinarash/printing-press/.runstate/dev-289aa4de/runs/20260805-211628-9cef41ba/working/catapult-openfield-connect-pp-cli"
BIN = os.path.join(D, "catapult-openfield-connect-pp-cli")

def helpout(args):
    try:
        r = subprocess.run([BIN]+list(args)+["--help"], capture_output=True, text=True, timeout=20)
        return r.stdout + r.stderr
    except Exception as e:
        return ""

# build command tree
help_cache = {}
def get_help(path):
    key = tuple(path)
    if key not in help_cache:
        help_cache[key] = helpout(path)
    return help_cache[key]

def subcommands(path):
    h = get_help(path)
    m = re.search(r"Available Commands:\n((?:  \S.*\n)+)", h)
    if not m: return []
    return [l.split()[0] for l in m.group(1).splitlines() if l.strip()]

root_cmds = subcommands([])
tree = {}
for c in root_cmds:
    tree[c] = subcommands([c])
print("ROOT COMMANDS:", root_cmds)
print()

# research novel features
rd = json.load(open("/Users/kristinarash/printing-press/.runstate/dev-289aa4de/runs/20260805-211628-9cef41ba/research.json"))
nfb = [(f["name"], f["command"]) for f in rd["novel_features_built"]]
nf_all = [(f["name"], f.get("command")) for f in rd.get("novel_features", [])]
print("NOVEL_FEATURES_BUILT:", nfb)
print("NOVEL_FEATURES (researched):", [n for n in nf_all if n not in nfb])
print()

files = {n: os.path.join(D, n) for n in ["README.md", "SKILL.md", "AGENTS.md"]}
findings = []

def add(f, ln, sev, msg):
    findings.append(f"{f}:{ln} [{sev}] {msg}")

flag_re = re.compile(r"--[a-z][a-z0-9-]*")

def valid_flags_for(path):
    h = get_help(path)
    return set(flag_re.findall(h))

global_flags = valid_flags_for([]) | valid_flags_for([root_cmds[0]] if root_cmds else [])

for fname, fpath in files.items():
    if not os.path.exists(fpath):
        print(f"MISSING FILE: {fpath}")
        continue
    lines = open(fpath).read().splitlines()
    print(f"=== {fname}: {len(lines)} lines ===")
    for i, line in enumerate(lines, 1):
        # command invocations
        for m in re.finditer(r"catapult-openfield-connect-pp-cli\s+([a-z][a-z0-9-]*)(?:\s+([a-z][a-z0-9-]*))?", line):
            c1, c2 = m.group(1), m.group(2)
            if c1 in ("help",): continue
            if c1 not in root_cmds:
                add(fname, i, "error", f"unknown command '{c1}' (line: {line.strip()[:100]})")
                continue
            cmdpath = [c1]
            if c2 and c2 in tree.get(c1, []):
                cmdpath = [c1, c2]
            elif c2 and tree.get(c1) and not c2.startswith("-"):
                # c2 might be an arg; only flag if the parent REQUIRES a subcommand and c2 looks like a subcommand attempt
                pass
            # validate flags on this line
            fl = set(flag_re.findall(line))
            if fl:
                vf = valid_flags_for(cmdpath) | global_flags
                bad = fl - vf
                for b in bad:
                    add(fname, i, "error", f"flag '{b}' not in '{' '.join(cmdpath)}' help (line: {line.strip()[:100]})")
        # params command references
        if re.search(r"\bparams\s+search\b", line) or re.search(r"catapult-openfield-connect-pp-cli\s+params\b", line):
            add(fname, i, "error", f"references dropped 'params' command (line: {line.strip()[:100]})")
        # placeholders
        if re.search(r"<cli>|<command>|<resource>", line):
            add(fname, i, "error", f"placeholder literal (line: {line.strip()[:100]})")
        # write verbs
        if re.search(r"\b(create|update|delete|modify|upload|write|edit)\b", line, re.I) and re.search(r"\b(activit|athlete|annotation|period|team|venue|record|data via the API|resource)", line, re.I):
            add(fname, i, "check-write", f"possible write claim: {line.strip()[:140]}")
        # brand casing
        if re.search(r"Catapult Openfield|Catapult openfield|OpenField Connect API|catapult openfield", line):
            if "Openfield" in line and "OpenField" not in line.replace("Openfield",""):
                add(fname, i, "warning", f"brand casing 'Openfield' (should be OpenField): {line.strip()[:120]}")
        # API key / OAuth claims
        if re.search(r"API key|OAuth|client_secret|username.*password", line, re.I):
            add(fname, i, "check-auth", f"auth claim: {line.strip()[:140]}")

print()
print("FINDINGS (%d):" % len(findings))
for f in findings:
    print(f)

# SKILL anti-triggers check
sk = open(files["SKILL.md"]).read()
print()
print("SKILL anti-trigger section present:", bool(re.search(r"NOT FOR|anti-trigger|Do not use|Don't use|should NOT", sk, re.I)))
m = re.search(r".{0,200}(NOT FOR|should NOT|Do not use this)[^\n]*", sk)
if m: print("context:", m.group(0)[-250:])

